"use client";
import LegacyPage from "../components/LegacyPage";
import "./page.css";

const TITLE = "Averages — Grades";
const BODY_HTML = "\n  <div class=\"page\">\n    <div class=\"topbar\">\n      <div>\n        <h1 class=\"title\">Your Grades</h1>\n        <p class=\"subtitle\" id=\"courseCountSub\">6 classes</p>\n      </div>\n      <div class=\"profile-menu-wrap\">\n        <button class=\"profile-btn\" id=\"profileBtn\" type=\"button\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-label=\"Profile and settings\"></button>\n        <div class=\"profile-menu\" id=\"profileMenu\" role=\"menu\" hidden>\n          <button class=\"profile-menu-item\" type=\"button\" role=\"menuitem\" data-action=\"settings\">Settings</button>\n          <button class=\"profile-menu-item signout\" type=\"button\" role=\"menuitem\" data-action=\"signout\">Sign out</button>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-inner\">\n        <div class=\"gpa-strip\">\n          <span class=\"gpa-label-wrap\" tabindex=\"0\" role=\"button\" aria-label=\"Estimated GPA — Unweighted, based on current grades\">\n            <span class=\"gpa-label\">Estimated GPA</span>\n            <span class=\"gpa-tooltip\" role=\"tooltip\">Unweighted, based on current grades and your GPA scale</span>\n          </span>\n          <span class=\"gpa-value\" id=\"gpaValue\" data-live=\"gpa:value\"></span>\n          <span class=\"gpa-label-wrap gpa-w\" tabindex=\"0\" role=\"button\" aria-label=\"Weighted GPA — Honors and AP classes count more\">\n            <span class=\"gpa-label\">Weighted</span>\n            <span class=\"gpa-tooltip\" role=\"tooltip\">Honors and AP classes count more. Edit the scale to change how much.</span>\n          </span>\n          <span class=\"gpa-value gpa-value-w\" id=\"gpaWeighted\"></span>\n          <button class=\"gpa-edit\" type=\"button\" id=\"gpaEditBtn\">Edit GPA scale</button>\n        </div>\n        <div class=\"section-head\">\n          <h2>All Courses</h2>\n          <span class=\"course-total\" id=\"courseTotal\"></span>\n        </div>\n        <table class=\"grades-table\">\n          <thead>\n            <tr>\n              <th>Class</th>\n              <th>Grade</th>\n              <th>Predicted Grade</th>\n              <th>Grade Calculator</th>\n            </tr>\n          </thead>\n          <tbody id=\"gradesBody\"></tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"grade-popup\" id=\"gradePopup\" role=\"tooltip\"></div>\n\n  <nav class=\"app-nav\" aria-label=\"Main navigation\">\n    <div class=\"app-nav-inner\" id=\"dock\">\n      <button class=\"nav-link\" type=\"button\" data-page=\"home\" data-href=\"/home\">\n        <span class=\"label\">Home</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"courses\" data-href=\"/courses\">\n        <span class=\"label\">Courses</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link active\" type=\"button\" data-page=\"grades\">\n        <span class=\"label\">Grades</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"assignments\" data-href=\"/assignments\">\n        <span class=\"label\">Assignments</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"files\" data-href=\"/files\">\n        <span class=\"label\">Files</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"calendar\" data-href=\"/calendar\">\n        <span class=\"label\">Calendar</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"messages\" data-href=\"/messages\">\n        <span class=\"label\">Messages</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"contacts\" data-href=\"/contacts\">\n        <span class=\"label\">Contacts</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"settings\" data-href=\"/settings\">\n        <span class=\"label\">Settings</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-more\" type=\"button\" id=\"navMore\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-controls=\"navMoreMenu\" aria-label=\"More pages\" hidden>\n        <span class=\"label\"><svg viewBox=\"0 0 16 4\" width=\"16\" height=\"4\" aria-hidden=\"true\"><circle cx=\"2\" cy=\"2\" r=\"1.75\"/><circle cx=\"8\" cy=\"2\" r=\"1.75\"/><circle cx=\"14\" cy=\"2\" r=\"1.75\"/></svg></span>\n        <span class=\"dot\"></span>\n      </button>\n    </div>\n    <div class=\"nav-more-menu\" id=\"navMoreMenu\" role=\"menu\" aria-label=\"More pages\" hidden></div>\n  </nav>\n\n  \n\n  <div class=\"modal-overlay\" id=\"calcModal\">\n    <div class=\"modal-box wide\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"calcCourseName\">\n      <div class=\"modal-box-scroll\">\n        <button class=\"modal-close\" id=\"calcCloseBtn\" type=\"button\" aria-label=\"Close grade calculator\">✕</button>\n        <h3 id=\"calcCourseName\"></h3>\n        <p class=\"modal-code\" id=\"calcCourseCode\">Final Grade Calculator</p>\n        <div class=\"calc-hero\">\n          <div class=\"calc-hero-label\" id=\"calcHeroLabel\">Current grade</div>\n          <div class=\"calc-hero-val\"><span id=\"calcHeroLetter\"></span><span class=\"calc-hero-pct\" id=\"calcHeroPct\"></span></div>\n        </div>\n        <div id=\"calcCategories\"></div>\n        <hr class=\"calc-divider\">\n        <h4 class=\"calc-final-heading\">Final Exam</h4>\n        <div class=\"calc-final-inputs\">\n          <div class=\"calc-final-field\">\n            <label for=\"calcFinalCurrent\">Current grade (%)</label>\n            <input type=\"number\" id=\"calcFinalCurrent\" min=\"0\" max=\"100\" step=\"0.1\">\n          </div>\n          <div class=\"calc-final-field\">\n            <label for=\"calcFinalWant\">Grade you want (%)</label>\n            <input type=\"number\" id=\"calcFinalWant\" min=\"0\" max=\"100\" step=\"0.1\" placeholder=\"e.g. 90\">\n          </div>\n          <div class=\"calc-final-field\">\n            <label for=\"calcFinalWeight\">Final exam weight (%)</label>\n            <input type=\"number\" id=\"calcFinalWeight\" min=\"1\" max=\"100\" value=\"20\">\n          </div>\n        </div>\n        <p class=\"calc-final-answer\" id=\"calcFinalAnswer\"></p>\n        <div class=\"calc-actions\">\n          <button class=\"calc-reset-btn\" id=\"calcResetBtn\" type=\"button\">Reset to real grades</button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  \n  \n";
const SCRIPT_JS = "\n    function avgIsId(v) { return /^\\d{1,24}$/.test(String(v == null ? '' : v)); }\n    function avgCourseQ(course) { return (avgIsId(course) ? 'id=' : 'course=') + encodeURIComponent(course == null ? '' : course); }\n    function avgAssignHref(course, title, id, extra) {\n      extra = extra || '';\n      if (avgIsId(id) && avgIsId(course)) return `/assignment?id=${id}${extra}`;\n      return `/assignment?course=${encodeURIComponent(course == null ? '' : course)}&title=${encodeURIComponent(title || '')}${avgIsId(id) ? `&id=${id}` : ''}${extra}`;\n    }\n\n    (function () {\n    var POTATO_CSS = \"body.potato-mode,body.potato-mode *,body.potato-mode *::before,body.potato-mode *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important;filter:none!important;text-shadow:none!important}html:has(body.potato-mode){scroll-behavior:auto!important}body.potato-mode,body.potato-mode *{font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif!important}body.potato-mode h1.title{font-style:normal!important;transform:none!important}body.potato-mode .trend.has-popup:focus-visible{outline:2px solid currentColor;outline-offset:2px}\";\n    function potatoOn() { return !!(document.body && document.body.classList.contains(\"potato-mode\")); }\n    function applyPotato() {\n      var on = false;\n      try { on = (JSON.parse(localStorage.getItem(\"averages_settings_options\") || \"{}\") || {}).potatoMode === true; } catch (e) {}\n      if (document.body) document.body.classList.toggle(\"potato-mode\", on);\n      if (!document.getElementById(\"potatoStyle\")) {\n        var st = document.createElement(\"style\");\n        st.id = \"potatoStyle\";\n        st.textContent = POTATO_CSS;\n        (document.head || document.documentElement).appendChild(st);\n      }\n      var EP = window.Element && Element.prototype;\n      if (EP && !EP.__potatoPatched) {\n        EP.__potatoPatched = true;\n        var anim = EP.animate;\n        if (anim) EP.animate = function (frames, opts) {\n          if (potatoOn()) opts = (typeof opts === \"number\" || opts == null) ? { duration: 0 } : Object.assign({}, opts, { duration: 0, delay: 0, endDelay: 0, iterations: 1 });\n          return anim.call(this, frames, opts);\n        };\n        var siv = EP.scrollIntoView;\n        if (siv) EP.scrollIntoView = function (arg) {\n          if (potatoOn() && arg && typeof arg === \"object\") arg = Object.assign({}, arg, { behavior: \"auto\" });\n          return siv.call(this, arg);\n        };\n        [\"scrollTo\", \"scrollBy\"].forEach(function (name) {\n          [EP, window].forEach(function (target) {\n            var fn = target[name];\n            if (!fn) return;\n            target[name] = function (a, b) {\n              if (potatoOn() && a && typeof a === \"object\") a = Object.assign({}, a, { behavior: \"auto\" });\n              return b === undefined ? fn.call(this, a) : fn.call(this, a, b);\n            };\n          });\n        });\n      }\n    }\n      applyPotato();\n      window.addEventListener('storage', function (e) { if (e.key === 'averages_settings_options') applyPotato(); });\n    })();\n\n    // Bottom nav \"More\" overflow. Shows as many pages as fit without\n    // cutting a label off (\"Cour...\"); the rest go in the More menu.\n    // The current page always stays in the bar.\n    (function () {\n      const nav = document.querySelector('.app-nav');\n      const inner = nav && nav.querySelector('.app-nav-inner');\n      const more = document.getElementById('navMore');\n      const menu = document.getElementById('navMoreMenu');\n      if (!inner || !more || !menu) return;\n      const links = Array.from(inner.querySelectorAll('.nav-link'));\n\n      const cut = () =>\n        inner.scrollWidth > inner.clientWidth + 1 ||\n        links.some(l => !l.hidden && l.querySelector('.label').scrollWidth > l.querySelector('.label').clientWidth + 1);\n\n      function fit() {\n        closeMenu();\n        links.forEach(l => { l.hidden = false; });\n        more.hidden = true;\n        if (!cut()) return;\n        more.hidden = false;\n        // Hide from the right, but never the current page.\n        for (let i = links.length - 1; i >= 1 && cut(); i--) {\n          if (!links[i].classList.contains('active')) links[i].hidden = true;\n        }\n        const hidden = links.filter(l => l.hidden);\n        more.classList.toggle('has-active', hidden.some(l => l.classList.contains('active')));\n        menu.textContent = '';\n        hidden.forEach(l => {\n          const item = document.createElement('button');\n          item.type = 'button';\n          item.className = 'nav-more-item' + (l.classList.contains('active') ? ' active' : '');\n          item.setAttribute('role', 'menuitem');\n          const text = document.createElement('span'); text.textContent = l.querySelector('.label').textContent; item.appendChild(text);\n          item.addEventListener('click', () => { closeMenu(); l.click(); });\n          menu.appendChild(item);\n        });\n      }\n\n      function openMenu() {\n        const navBox = nav.getBoundingClientRect();\n        const innerBox = inner.getBoundingClientRect();\n        menu.style.right = Math.max(0, navBox.right - innerBox.right) + 'px';\n        menu.hidden = false;\n        nav.classList.add('more-open');\n        more.setAttribute('aria-expanded', 'true');\n        const first = menu.querySelector('.nav-more-item');\n        if (first) first.focus();\n      }\n      function closeMenu() {\n        if (menu.hidden) return;\n        menu.hidden = true;\n        nav.classList.remove('more-open');\n        more.setAttribute('aria-expanded', 'false');\n      }\n\n      more.addEventListener('click', e => {\n        e.stopPropagation();\n        menu.hidden ? openMenu() : closeMenu();\n      });\n      document.addEventListener('click', e => { if (!menu.contains(e.target)) closeMenu(); });\n      document.addEventListener('keydown', e => {\n        if (e.key === 'Escape' && !menu.hidden) { closeMenu(); more.focus(); }\n        if (!menu.hidden && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {\n          const items = Array.from(menu.querySelectorAll('.nav-more-item'));\n          const i = items.indexOf(document.activeElement);\n          const next = items[(i + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length];\n          if (next) { e.preventDefault(); next.focus(); }\n        }\n      });\n\n      fit();\n      if (window.ResizeObserver) new ResizeObserver(fit).observe(nav);\n      else window.addEventListener('resize', fit);\n      if (document.fonts && document.fonts.ready) document.fonts.ready.then(fit);\n    })();\n  \n\n\n    (function () {\n      function darken(hex, amount) {\n        const n = parseInt(hex.slice(1), 16);\n        const r = Math.max(0, ((n >> 16) & 255) * (1 - amount));\n        const g = Math.max(0, ((n >> 8) & 255) * (1 - amount));\n        const b = Math.max(0, (n & 255) * (1 - amount));\n        return '#' + [r, g, b].map(v => Math.round(v).toString(16).padStart(2, '0')).join('');\n      }\n      function applyAppearance() {\n        let saved = null;\n        try {\n          const raw = localStorage.getItem('averages_appearance');\n          if (raw) saved = JSON.parse(raw);\n        } catch {}\n        if (!saved) return;\n        const root = document.documentElement.style;\n        if (saved.accent) {\n          root.setProperty('--accent', saved.accent);\n          root.setProperty('--accent-dark', saved.accentDark || darken(saved.accent, 0.22));\n        }\n        if (saved.background === 'white') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#f4f4f6';\n        } else if (saved.background === 'black') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#0c0c0e';\n        } else if (saved.background) {\n          document.body.style.backgroundImage = `url(\"${saved.background}\")`;\n          document.body.style.backgroundColor = '';\n        }\n      }\n      applyAppearance();\n      window.addEventListener('storage', e => {\n        if (e.key === 'averages_appearance') applyAppearance();\n      });\n    })();\n\n    // ------------------------------------------------------------------\n    // Sample data — same six courses as /courses's COURSES array\n    // (same id/name/color/grade/predicted/updated values), trimmed to\n    // what this page's wireframe called for: Class, Grade, Predicted\n    // Grade, Grade Calculator. No Assignments/Updated columns here —\n    // those belong to the All Courses list, not the Grades overview.\n    // ------------------------------------------------------------------\n\n    const AVERAGES_COURSE_CUSTOM_KEY = 'averages_course_custom';\n    const AVERAGES_COURSE_ORDER_KEY = 'averages_course_order';\n    function loadCourseCustom() {\n      try {\n        const raw = localStorage.getItem(AVERAGES_COURSE_CUSTOM_KEY);\n        if (raw) return JSON.parse(raw);\n      } catch {}\n      return {};\n    }\n    function loadCourseOrder() {\n      try {\n        const raw = localStorage.getItem(AVERAGES_COURSE_ORDER_KEY);\n        if (raw) return JSON.parse(raw);\n      } catch {}\n      return null;\n    }\n    const COURSE_SUBJECTS = [\n      [/\\bchem/, '🧪', '#1b7f67'],\n      [/\\bbio|anatom|physiolog/, '🧬', '#387f33'],\n      [/\\bphysical ed|(^|[^a-z])p\\.?e\\.?($|[^a-z])|fitness|\\bweight/, '🏃', '#c2562b'],\n      [/\\bhealth/, '🩺', '#c0404a'],\n      [/\\bphysics/, '⚛️', '#4a56b8'],\n      [/astronom/, '🔭', '#3b3f8f'],\n      [/environment|\\bearth|geolog/, '🌍', '#2f7f63'],\n      [/robotic/, '🤖', '#55697d'],\n      [/computer|programming|coding|\\bcs[ap]?\\b|software/, '💻', '#2d6f8f'],\n      [/engineer/, '⚙️', '#6a6478'],\n      [/government|civics|politic/, '🏛️', '#2f4f8a'],\n      [/econ/, '📈', '#2e7d4f'],\n      [/psych/, '🧠', '#9a4583'],\n      [/geograph/, '🗺️', '#4c7a5a'],\n      [/histor/, '📜', '#9a5a2a'],\n      [/statistic|\\bstats?\\b/, '📊', '#2f72a8'],\n      [/geometr|\\btrig/, '📐', '#3e64b0'],\n      [/calc|algebra|\\bmath/, '🧮', '#2f5fb3'],\n      [/english|literature|\\blit\\b|writing|composition|language arts|reading/, '📖', '#a63a4f'],\n      [/spanish|french|german|chinese|mandarin|japanese|korean|latin|italian|\\basl\\b|sign language|language/, '🗣️', '#7a4fae'],\n      [/theat|drama/, '🎭', '#a3364b'],\n      [/music|band|choir|orchestra|chorus/, '🎵', '#6b48a8'],\n      [/photo/, '📷', '#4f5d6e'],\n      [/culinary|cooking|\\bfoods?\\b|nutrition/, '🍳', '#b05a26'],\n      [/\\barts?\\b|drawing|painting|ceramic|sculpt|design/, '🎨', '#b03f7a'],\n      [/business|marketing|accounting|financ/, '💼', '#3d5f6e'],\n      [/journalism|yearbook|newspaper/, '📰', '#5c5c6e'],\n      [/science/, '🔬', '#2b7b8c'],\n    ];\n    function courseSubject(name) {\n      const n = String(name || '').toLowerCase();\n      return COURSE_SUBJECTS.find(([re]) => re.test(n)) || null;\n    }\n\n    function applyCourseCustomizationsInPlace(courses) {\n      const custom = loadCourseCustom();\n      // Mutates each course object's own fields in place (never clones,\n      // never reassigns `courses` itself) so the `const COURSES = [...]`\n      // literal a few lines below stays exactly that — a literal array —\n      // for scripts/port-pages.mjs's data-overrides transform to match\n      // and rewrite for live Schoology data. This function only edits\n      // the array's contents/order after that binding already exists.\n      courses.forEach(c => {\n        const subject = courseSubject(c.name);\n        if (subject) c.color = subject[2];\n        Object.assign(c, custom[c.id] || {});\n      });\n      const order = loadCourseOrder();\n      if (order && order.length) {\n        const byId = new Map(courses.map(c => [c.id, c]));\n        const ordered = order.filter(id => byId.has(id)).map(id => byId.get(id));\n        // A course not present in the saved order (e.g. added to the demo\n        // data after the order was saved) still shows up, just appended.\n        courses.forEach(c => { if (!order.includes(c.id)) ordered.push(c); });\n        courses.splice(0, courses.length, ...ordered);\n      }\n    }\n    const COURSES = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.COURSES) || [\n      { id: 'apchem', name: 'AP Chemistry', code: '76_M0431', period: 2, teacher: 'Alvarez', section: '1204', color: '#a67a22', grade: 'B+', pct: 87, predicted: 'A-', predictedPct: 91, trend: 'up' },\n      { id: 'algebra2', name: 'Algebra II', code: '76_S0512', period: 3, teacher: 'Whitfield', section: '1188', color: '#5b6ea3', grade: 'A', pct: 95, predicted: 'A', predictedPct: 95, trend: 'flat' },\n      { id: 'english10', name: 'English 10', code: '76_F0288', period: 4, teacher: 'Cho', section: '1350', color: '#6b8f5e', grade: 'C+', pct: 78, predicted: 'C', predictedPct: 74, trend: 'down' },\n      { id: 'ushistory', name: 'U.S. History', code: '76_R0367', period: 1, teacher: 'Bennett', section: '1092', color: '#a15c4f', grade: 'A-', pct: 91, predicted: 'A-', predictedPct: 91, trend: 'flat' },\n      { id: 'spanish3', name: 'Spanish III', code: '76_G0295', period: 5, teacher: 'Ortiz', section: '1417', color: '#8a6ba1', grade: 'B', pct: 84, predicted: 'B+', predictedPct: 88, trend: 'up' },\n      { id: 'pe', name: 'PE', code: '76_P0300', period: 6, teacher: 'Reyes', section: '1125', color: '#4f8c8a', grade: 'A', pct: 97, predicted: 'A', predictedPct: 97, trend: 'flat' },\n    ];\n    applyCourseCustomizationsInPlace(COURSES);\n    COURSES.forEach(c => { ['code', 'period', 'teacher', 'section'].forEach(k => { if (c[k] === undefined || c[k] === null) c[k] = ''; }); });\n    function courseMetaLine(c) {\n      const left = [c.period !== '' ? `Pd:${c.period}` : '', c.teacher].filter(Boolean).join(' ');\n      return [left, c.section].filter(Boolean).join(' - ');\n    }\n\n    function findCourse(id) { return COURSES.find(c => c.id === id); }\n\n    // Escapes a value for interpolation into an HTML string — safe both in\n    // text positions and inside quoted attribute values. Every `${...}`\n    // below carrying course, gradebook or assignment data must go through\n    // it: in the live app those strings come from teachers, so rendered raw\n    // into innerHTML a title like `<img src=x onerror=...>` executes in our\n    // own origin. Same helper as /home — see its comment for the full\n    // reasoning. Do NOT wrap values that are themselves markup (the chart\n    // fragments, CALC_ICON, calcAssignQualifier).\n    function escapeHtml(value) {\n      return String(value).replace(/[&<>\"']/g, ch => (\n        { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[ch]\n      ));\n    }\n\n    // Assignment-score history behind the Predicted-grade reasoning\n    // popup — copied verbatim from /courses's HISTORY (same course\n    // ids, same predictedPct/trend values).\n    const HISTORY = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.HISTORY) || {\n      apchem: { points: [72, 79, 84, 88, 90], dates: ['Aug 4', 'Aug 8', 'Aug 12', 'Aug 18', 'Aug 24'] },\n      algebra2: { points: [94, 96, 93, 97, 95], dates: ['Aug 3', 'Aug 7', 'Aug 11', 'Aug 17', 'Aug 23'] },\n      english10: { points: [88, 82, 79, 76, 73], dates: ['Aug 4', 'Aug 8', 'Aug 12', 'Aug 18', 'Aug 24'] },\n      ushistory: { points: [89, 93, 88, 92, 90], dates: ['Aug 4', 'Aug 8', 'Aug 12', 'Aug 18', 'Aug 24'] },\n      spanish3: { points: [76, 80, 83, 85, 87], dates: ['Aug 3', 'Aug 7', 'Aug 11', 'Aug 17', 'Aug 23'] },\n      pe: { points: [96, 98, 95, 97, 96], dates: ['Aug 2', 'Aug 6', 'Aug 10', 'Aug 16', 'Aug 22'] },\n    };\n\n    // ------------------------------------------------------------------\n    // Gradebook data — new for this page. Each course's real weighted\n    // category breakdown, feeding both the read-only Gradebook pop-out\n    // and the editable Grade Calculator below. `graded:false` entries\n    // are what the Calculator's \"what-if\" score inputs apply to; the\n    // rest are locked-in real scores. Category weights always sum to\n    // 100 per course, matching a real Schoology-style weighted gradebook.\n    // ------------------------------------------------------------------\n    const GRADEBOOK = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.GRADEBOOK) || {\n      apchem: { categories: [\n        { name: 'Tests', weight: 40, assignments: [\n          { title: 'Unit 1 Test', score: 42, points: 50, graded: true },\n          { title: 'Unit 2 Test', score: 45, points: 50, graded: true },\n        ]},\n        { name: 'Labs', weight: 30, assignments: [\n          { title: 'Titration Lab', score: 18, points: 20, graded: true },\n          { title: 'Lab Report #3', score: 17, points: 20, graded: true },\n          { title: 'Lab Report #4', points: 20, graded: false },\n        ]},\n        { name: 'Homework', weight: 30, assignments: [\n          { title: 'Problem Set 1', score: 9, points: 10, graded: true },\n          { title: 'Problem Set 2', score: 8, points: 10, graded: true },\n          { title: 'Problem Set 3', score: 10, points: 10, graded: true },\n        ]},\n      ]},\n      algebra2: { categories: [\n        { name: 'Tests', weight: 50, assignments: [\n          { title: 'Unit 2 Test', score: 47, points: 50, graded: true },\n          { title: 'Unit 3 Test', score: 48, points: 50, graded: true },\n        ]},\n        { name: 'Quizzes', weight: 30, assignments: [\n          { title: 'Quiz 4', score: 9, points: 10, graded: true },\n          { title: 'Quiz 5', score: 10, points: 10, graded: true },\n          { title: 'Quiz 6', points: 10, graded: false },\n        ]},\n        { name: 'Homework', weight: 20, assignments: [\n          { title: 'Problem Set 6', score: 10, points: 10, graded: true },\n          { title: 'Problem Set 7', score: 9, points: 10, graded: true },\n        ]},\n      ]},\n      english10: { categories: [\n        { name: 'Essays', weight: 45, assignments: [\n          { title: 'Essay 1: Narrative', score: 34, points: 40, graded: true },\n          { title: 'Essay 2: Rhetorical Analysis', score: 27, points: 40, graded: true },\n        ]},\n        { name: 'Discussions', weight: 25, assignments: [\n          { title: 'Discussion 1', score: 8, points: 10, graded: true },\n          { title: 'Chapter 6 Discussion', points: 10, graded: false },\n          { title: 'Discussion 3', score: 7, points: 10, graded: true },\n        ]},\n        { name: 'Homework', weight: 30, assignments: [\n          { title: 'Reading Log 1', score: 8, points: 10, graded: true },\n          { title: 'Reading Log 2', score: 7, points: 10, graded: true },\n          { title: 'Reading Log 3', score: 9, points: 10, graded: true },\n        ]},\n      ]},\n      ushistory: { categories: [\n        { name: 'Tests', weight: 40, assignments: [\n          { title: 'Unit 1 Test', score: 46, points: 50, graded: true },\n          { title: 'Unit 2 Test', score: 45, points: 50, graded: true },\n        ]},\n        { name: 'Essays', weight: 30, assignments: [\n          { title: 'DBQ Essay', score: 36, points: 40, graded: true },\n          { title: 'Reading Response', points: 40, graded: false },\n        ]},\n        { name: 'Homework', weight: 30, assignments: [\n          { title: 'Source Analysis 1', score: 9, points: 10, graded: true },\n          { title: 'Source Analysis 2', score: 9, points: 10, graded: true },\n          { title: 'Source Analysis 3', score: 10, points: 10, graded: true },\n        ]},\n      ]},\n      spanish3: { categories: [\n        { name: 'Tests', weight: 35, assignments: [\n          { title: 'Unit 2 Test', score: 40, points: 50, graded: true },\n          { title: 'Unit 3 Test', score: 43, points: 50, graded: true },\n        ]},\n        { name: 'Quizzes', weight: 30, assignments: [\n          { title: 'Vocab Quiz 4', score: 8, points: 10, graded: true },\n          { title: 'Vocab Quiz 5', score: 9, points: 10, graded: true },\n          { title: 'Vocab Worksheet', points: 10, graded: false },\n        ]},\n        { name: 'Homework', weight: 35, assignments: [\n          { title: 'Workbook Ch. 5', score: 9, points: 10, graded: true },\n          { title: 'Workbook Ch. 6', score: 8, points: 10, graded: true },\n          { title: 'Workbook Ch. 7', score: 8, points: 10, graded: true },\n        ]},\n      ]},\n      pe: { categories: [\n        { name: 'Participation', weight: 40, assignments: [\n          { title: 'Week 1', score: 10, points: 10, graded: true },\n          { title: 'Week 2', score: 10, points: 10, graded: true },\n          { title: 'Week 3', score: 9, points: 10, graded: true },\n        ]},\n        { name: 'Skills Tests', weight: 25, assignments: [\n          { title: 'Fitness Test', score: 47, points: 50, graded: true },\n          { title: 'Unit Skills Check', score: 49, points: 50, graded: true },\n        ]},\n        { name: 'Homework', weight: 15, assignments: [\n          { title: 'Wellness Log', score: 10, points: 10, graded: true },\n          { title: 'Reflection', score: 9, points: 10, graded: true },\n        ]},\n        { name: 'Demonstrated Skills', weight: 20, assignments: [\n          { title: 'Teamwork & Communication', score: 5, points: 5, graded: true },\n          { title: 'Sportsmanship', score: 5, points: 5, graded: true },\n          { title: 'Skill Execution', score: 4, points: 5, graded: true },\n          { title: 'Effort & Participation', score: 5, points: 5, graded: true },\n          { title: 'Safety Awareness', score: 3, points: 5, graded: true },\n        ]},\n      ]},\n    };\n\n    const AV_LIVE = !!(window.__AVERAGES__ && window.__AVERAGES__.data) && window.__AVERAGES__.mode !== 'demo';\n    const AV_DATA = AV_LIVE ? window.__AVERAGES__.data : {};\n    // GRADEBOOK signed in is the bundle's, never the samples; each entry is\n    // tidied once so nothing below meets a missing number.\n    if (AV_LIVE) {\n      if (!AV_DATA.GRADEBOOK || typeof AV_DATA.GRADEBOOK !== 'object') Object.keys(GRADEBOOK).forEach(k => { delete GRADEBOOK[k]; });\n      Object.keys(GRADEBOOK).forEach(k => {\n        const entry = GRADEBOOK[k];\n        const cats = entry && Array.isArray(entry.categories) ? entry.categories : [];\n        GRADEBOOK[k] = { categories: cats.filter(c => c && typeof c === 'object').map(c => ({\n          name: String(c.name || 'Category'),\n          weight: Number(c.weight) > 0 ? Number(c.weight) : 0,\n          assignments: (Array.isArray(c.assignments) ? c.assignments : []).filter(a => a && typeof a === 'object').map(a => {\n            const n = a.score === '' || a.score === null || a.score === undefined ? NaN : Number(a.score);\n            const score = isFinite(n) ? n : undefined;\n            return { title: String(a.title || 'Untitled'), score, points: Number(a.points) > 0 ? Number(a.points) : 0, graded: !!a.graded && score !== undefined, id: a.id };\n          }),\n        })) };\n      });\n    }\n    function gbWeighted(gb) { return !!gb && Array.isArray(gb.categories) && gb.categories.some(c => Number(c.weight) > 0); }\n    function gbWeightLabel(cat, weighted) {\n      if (Number(cat.weight) > 0) return `${cat.weight}% of grade`;\n      return weighted ? 'Not counted' : 'Counts by points';\n    }\n\n    const GRADE_COLOR = { a: 'var(--grade-good)', b: 'var(--grade-b)', c: 'var(--grade-mid)', d: 'var(--grade-d)', f: 'var(--grade-bad)' };\n    function gradeBand(letter) {\n      const l = letter[0];\n      if (l === 'A') return 'a';\n      if (l === 'B') return 'b';\n      if (l === 'C') return 'c';\n      if (l === 'D') return 'd';\n      return 'f';\n    }\n    // Standard 10-point scale, used to turn a computed percentage (e.g.\n    // from the Calculator's live recompute) back into a letter grade —\n    // COURSES' own grade/pct pairs were hand-set to plausible values\n    // rather than derived from this, so this is only used for numbers\n    // this page itself computes.\n    function letterFromPct(pct) {\n      if (pct >= 97) return 'A+';\n      if (pct >= 93) return 'A';\n      if (pct >= 90) return 'A-';\n      if (pct >= 87) return 'B+';\n      if (pct >= 83) return 'B';\n      if (pct >= 80) return 'B-';\n      if (pct >= 77) return 'C+';\n      if (pct >= 73) return 'C';\n      if (pct >= 70) return 'C-';\n      if (pct >= 67) return 'D+';\n      if (pct >= 63) return 'D';\n      if (pct >= 60) return 'D-';\n      return 'F';\n    }\n    const TREND_ARROW = { up: '↗', down: '↘', flat: '–' };\n\n    const GPA_SCALE = {\n      'A+': 4.0, 'A': 4.0, 'A-': 3.7,\n      'B+': 3.3, 'B': 3.0, 'B-': 2.7,\n      'C+': 2.3, 'C': 2.0, 'C-': 1.7,\n      'D+': 1.3, 'D': 1.0, 'D-': 0.7,\n      'F': 0.0,\n    };\n    // The student's own scale (Edit GPA scale, public/js/averages-gpa.js) when it's there\n    function gpaPair() {\n      if (window.AveragesGPA) return window.AveragesGPA.compute(COURSES.map(c => ({ id: String(c.id), name: c.name, grade: c.grade })));\n      const graded = COURSES.filter(c => GPA_SCALE[c.grade] !== undefined);\n      const u = graded.length ? graded.reduce((sum, c) => sum + GPA_SCALE[c.grade], 0) / graded.length : null;\n      return { unweighted: u, weighted: u };\n    }\n    function computeGPA() { return gpaPair().unweighted; }\n    function gpaColor(gpa) {\n      if (gpa >= 3.7) return 'var(--grade-good)';\n      if (gpa >= 3.0) return 'var(--grade-b)';\n      if (gpa >= 2.3) return 'var(--grade-mid)';\n      if (gpa >= 1.7) return 'var(--grade-d)';\n      return 'var(--grade-bad)';\n    }\n    function renderGPA() {\n      const gpa = computeGPA();\n      const gpaValueEl = document.getElementById('gpaValue');\n      gpaValueEl.textContent = gpa === null ? '—' : gpa.toFixed(2);\n      gpaValueEl.style.color = gpa === null ? '' : gpaColor(gpa);\n      const w = gpaPair().weighted, wEl = document.getElementById('gpaWeighted');\n      wEl.textContent = w === null ? '—' : w.toFixed(2);\n      wEl.style.color = w === null ? '' : gpaColor(Math.min(4, w));\n    }\n    document.getElementById('gpaEditBtn').addEventListener('click', () => {\n      if (window.AveragesGPA) window.AveragesGPA.edit(COURSES.map(c => ({ id: String(c.id), name: c.name, grade: c.grade })), renderGPA);\n    });\n    window.addEventListener('storage', e => { if (e.key === 'averages_settings_options') renderGPA(); });\n\n    // ------------------------------------------------------------------\n    // Predicted-grade reasoning popup — ported verbatim from\n    // /courses//home.\n    // ------------------------------------------------------------------\n    function niceBounds(values) {\n      const min = Math.min(...values), max = Math.max(...values);\n      let lo = Math.floor((min - 6) / 10) * 10;\n      let hi = Math.ceil((max + 6) / 10) * 10;\n      lo = Math.max(0, lo);\n      hi = Math.min(100, hi);\n      if (hi - lo < 20) { hi = Math.min(100, lo + 20); }\n      return [lo, hi];\n    }\n\n    function groupSameDay(h) {\n      const days = [];\n      h.points.forEach((p, i) => {\n        const d = h.dates[i];\n        const last = days[days.length - 1];\n        if (last && last.date === d) { last.sum += p; last.n++; }\n        else days.push({ date: d, sum: p, n: 1 });\n      });\n      return Object.assign({}, h, {\n        points: days.map(x => Math.round(x.sum / x.n)),\n        dates: days.map(x => x.n > 1 ? `${x.date} ×${x.n}` : x.date),\n      });\n    }\n    function buildGradeChartSVG(course) {\n      if (!HISTORY[course.id] || !Array.isArray(HISTORY[course.id].points) || !HISTORY[course.id].points.length) return '<p class=\"trend-note\">No graded work yet. The trend shows up after the first grades.</p>';\n      const hist = groupSameDay(HISTORY[course.id]);\n      const allLabels = hist.dates.concat(['Predicted']);\n      const allValues = hist.points.concat([course.predictedPct]);\n      const [yLo, yHi] = niceBounds(allValues);\n\n      const W = 240, H = 108;\n      const padL = 26, padR = 6, padT = 10, padB = 16;\n      const plotW = W - padL - padR, plotH = H - padT - padB;\n\n      const xFor = i => padL + (i / (allLabels.length - 1)) * plotW;\n      const yFor = v => padT + plotH - ((v - yLo) / (yHi - yLo)) * plotH;\n\n      const yTicks = [yLo, Math.round((yLo + yHi) / 2), yHi];\n      const gridlines = yTicks.map(t => `\n        <line x1=\"${padL}\" x2=\"${W - padR}\" y1=\"${yFor(t)}\" y2=\"${yFor(t)}\" stroke=\"var(--border)\" stroke-width=\"1\"/>\n        <text x=\"${padL - 6}\" y=\"${yFor(t) + 3}\" text-anchor=\"end\" font-size=\"8\" fill=\"var(--text-faint)\">${t}%</text>\n      `).join('');\n\n      const actualPts = hist.points.map((v, i) => [xFor(i), yFor(v)]);\n      const actualLine = actualPts.map(p => p.join(',')).join(' ');\n      const actualMarkers = actualPts.map(([x, y]) => `\n        <circle cx=\"${x}\" cy=\"${y}\" r=\"4\" fill=\"${escapeHtml(course.color)}\" stroke=\"var(--panel-bg)\" stroke-width=\"2\"/>\n      `).join('');\n\n      const predX = xFor(allLabels.length - 1), predY = yFor(course.predictedPct);\n      const lastActual = actualPts[actualPts.length - 1];\n\n      const predictedBand = `x=\"${lastActual[0]}\" y=\"${padT}\" width=\"${predX - lastActual[0]}\" height=\"${plotH}\"`;\n      const stripeDefs = `\n        <pattern id=\"predStripesGrades\" patternUnits=\"userSpaceOnUse\" width=\"6\" height=\"6\" patternTransform=\"rotate(45)\">\n          <rect width=\"6\" height=\"6\" fill=\"${escapeHtml(course.color)}\" fill-opacity=\"0.08\"/>\n          <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"6\" stroke=\"${escapeHtml(course.color)}\" stroke-width=\"2.2\"/>\n        </pattern>\n      `;\n\n      const xLabels = allLabels.map((lab, i) => `\n        <text x=\"${xFor(i)}\" y=\"${H - 2}\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"var(--text-faint)\">${escapeHtml(lab === 'Predicted' ? 'Pred.' : lab)}</text>\n      `).join('');\n\n      return `\n        <svg viewBox=\"0 0 ${W} ${H}\" width=\"${W}\" height=\"${H}\" role=\"img\" aria-label=\"Line chart of ${escapeHtml(course.name)} assignment scores trending toward a predicted grade of ${escapeHtml(course.predictedPct)} percent\">\n          <defs>${stripeDefs}</defs>\n          ${gridlines}\n          <rect ${predictedBand} fill=\"url(#predStripesGrades)\" stroke=\"none\"/>\n          <polyline points=\"${actualLine}\" fill=\"none\" stroke=\"${escapeHtml(course.color)}\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n          <line x1=\"${lastActual[0]}\" y1=\"${lastActual[1]}\" x2=\"${predX}\" y2=\"${predY}\" stroke=\"${escapeHtml(course.color)}\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-dasharray=\"3 3\"/>\n          ${actualMarkers}\n          <circle cx=\"${predX}\" cy=\"${predY}\" r=\"4.5\" fill=\"var(--panel-bg)\" stroke=\"${escapeHtml(course.color)}\" stroke-width=\"2\"/>\n          <text x=\"${predX}\" y=\"${predY - 10}\" text-anchor=\"end\" font-size=\"8.5\" font-weight=\"800\" fill=\"var(--text-dark)\">${escapeHtml(course.predictedPct)}%</text>\n          ${xLabels}\n        </svg>\n      `;\n    }\n\n    const TREND_WORD = { up: 'Trending up', down: 'Trending down', flat: 'Holding steady' };\n\n    function renderGradePopup(course) {\n      const hist = HISTORY[course.id];\n      if (!hist || !Array.isArray(hist.points) || !hist.points.length) return `<h3>${escapeHtml(course.name)}</h3><p class=\"popup-sub\">No grades yet. Trend and prediction show after the first grade.</p>`;\n      const first = hist.points[0], lastGraded = hist.points[hist.points.length - 1];\n      return `\n        <h3>${escapeHtml(course.name)}</h3>\n        <p class=\"popup-sub\">${TREND_WORD[course.trend]}: <strong>${escapeHtml(first)}% → ${escapeHtml(lastGraded)}%</strong> over the last ${hist.points.length} graded assignments, predicting <strong>${escapeHtml(course.predictedPct)}%</strong> (${escapeHtml(course.predicted)}).</p>\n        ${buildGradeChartSVG(course)}\n        <p class=\"popup-foot\">Predicted grade extrapolates this trend — not a copy of the current grade.</p>\n      `;\n    }\n\n    const gradePopup = document.getElementById('gradePopup');\n    let popupHideTimer = null;\n\n    function showGradePopup(trigger) {\n      clearTimeout(popupHideTimer);\n      const course = findCourse(trigger.dataset.course);\n      if (!course || !HISTORY[course.id]) return;\n      gradePopup.innerHTML = renderGradePopup(course);\n      gradePopup.classList.add('show');\n      trigger.setAttribute('aria-expanded', 'true');\n\n      const rect = trigger.getBoundingClientRect();\n      const popupRect = gradePopup.getBoundingClientRect();\n      let left = rect.left + rect.width / 2 - popupRect.width / 2;\n      left = Math.max(10, Math.min(left, window.innerWidth - popupRect.width - 10));\n      let top = rect.top - popupRect.height - 10;\n      if (top < 10) top = rect.bottom + 10;\n      gradePopup.style.left = `${left}px`;\n      gradePopup.style.top = `${top}px`;\n    }\n\n    function hideGradePopup() {\n      gradePopup.classList.remove('show');\n      document.querySelectorAll('.trend.has-popup[aria-expanded=\"true\"]').forEach(t => t.setAttribute('aria-expanded', 'false'));\n    }\n\n    function bindGradePopupTriggers() {\n      document.querySelectorAll('.trend.has-popup').forEach(trigger => {\n        trigger.addEventListener('mouseenter', () => showGradePopup(trigger));\n        trigger.addEventListener('focus', () => showGradePopup(trigger));\n        trigger.addEventListener('mouseleave', () => { popupHideTimer = setTimeout(hideGradePopup, 80); });\n        trigger.addEventListener('blur', hideGradePopup);\n        trigger.addEventListener('keydown', e => { if (e.key === 'Escape') { hideGradePopup(); trigger.blur(); } });\n      });\n    }\n\n    const CALC_ICON = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"5\" y=\"2\" width=\"14\" height=\"20\" rx=\"2\"/><line x1=\"8\" y1=\"6\" x2=\"16\" y2=\"6\"/><line x1=\"8\" y1=\"11\" x2=\"8.01\" y2=\"11\"/><line x1=\"12\" y1=\"11\" x2=\"12.01\" y2=\"11\"/><line x1=\"16\" y1=\"11\" x2=\"16.01\" y2=\"11\"/><line x1=\"8\" y1=\"15\" x2=\"8.01\" y2=\"15\"/><line x1=\"12\" y1=\"15\" x2=\"12.01\" y2=\"15\"/><line x1=\"16\" y1=\"15\" x2=\"16.01\" y2=\"15\"/></svg>';\n\n    const gradesBody = document.getElementById('gradesBody');\n\n    function renderGradesTable() {\n      gradesBody.innerHTML = '';\n      COURSES.forEach(c => {\n        const tr = document.createElement('tr');\n        tr.dataset.id = c.id;\n        tr.tabIndex = 0;\n        tr.setAttribute('role', 'link');\n        tr.setAttribute('aria-label', `Open ${c.name}'s gradebook`);\n        tr.innerHTML = `\n          <td>\n            <div class=\"course-row\">\n              <span class=\"course-tick\" style=\"background:${escapeHtml(c.color)}\"></span>\n              <div class=\"course-row-text\">\n                <div class=\"course-row-top\">\n                  <span class=\"course-row-name\">${escapeHtml(c.name)}</span>\n                  <span class=\"course-row-code\">${escapeHtml(c.code)}</span>\n                </div>\n                <div class=\"course-row-meta\">${escapeHtml(courseMetaLine(c))}</div>\n              </div>\n            </div>\n          </td>\n          <td><span class=\"grade-val ${gradeBand(c.grade)}\"><span data-live=\"${escapeHtml(c.id)}:grade\">${escapeHtml(c.grade)}</span>${c.grade === '—' ? '' : `<span class=\"grade-pct\" data-live=\"${escapeHtml(c.id)}:pct\">${escapeHtml(c.pct)}%</span>`}</span></td>\n          <td><span class=\"trend has-popup ${escapeHtml(c.trend)}\" tabindex=\"0\" role=\"button\" aria-haspopup=\"true\" aria-label=\"${c.predicted === '—' ? `${escapeHtml(c.name)} has no grades yet. Show more.` : `Why is ${escapeHtml(c.name)} predicted ${escapeHtml(c.predicted)}, ${escapeHtml(c.predictedPct)} percent? Show reasoning.`}\" data-course=\"${escapeHtml(c.id)}\"><span class=\"arrow\">${TREND_ARROW[c.trend]}</span><span data-live=\"${escapeHtml(c.id)}:predicted\">${escapeHtml(c.predicted)}</span>${c.predicted === '—' ? '' : `<span class=\"grade-pct\" data-live=\"${escapeHtml(c.id)}:predictedPct\">(${escapeHtml(c.predictedPct)}%)</span>`}</span></td>\n          <td class=\"calc-cell\" data-course=\"${escapeHtml(c.id)}\"><button class=\"calc-btn\" type=\"button\" data-course=\"${escapeHtml(c.id)}\" aria-label=\"Open the grade calculator for ${escapeHtml(c.name)}\">${CALC_ICON}Calculate</button></td>\n        `;\n        gradesBody.appendChild(tr);\n      });\n      document.getElementById('courseTotal').textContent = `${COURSES.length} total`;\n      document.getElementById('courseCountSub').textContent = `${COURSES.length} classes`;\n      bindGradePopupTriggers();\n    }\n    renderGradesTable();\n    renderGPA();\n    window.__averagesLiveGrades = function () {\n      renderGradesTable();\n      renderGPA();\n    };\n    window.__averagesExtraLanded = function (name) {\n      if (name !== 'people') return;\n      document.querySelectorAll('#gradesBody tr[data-id]').forEach(tr => {\n        const c = COURSES.find(x => String(x.id) === tr.dataset.id);\n        const meta = tr.querySelector('.course-row-meta');\n        if (!c || !meta) return;\n        const text = courseMetaLine(c);\n        const last = meta.lastChild;\n        if (last && last.nodeType === 3) last.nodeValue = text;\n        else meta.appendChild(document.createTextNode(text));\n      });\n    };\n\n    function gradesRowNavTarget(el) {\n      if (el.closest('.trend') || el.closest('.calc-cell')) return null;\n      const row = el.closest('tr[data-id]');\n      return row ? row.dataset.id : null;\n    }\n    function goToGradebook(id) { window.location.href = `/gradebook?${avgCourseQ(id)}`; }\n    gradesBody.addEventListener('click', e => {\n      const calcCell = e.target.closest('.calc-cell');\n      if (calcCell) { openCalcModal(calcCell.dataset.course); return; }\n      const id = gradesRowNavTarget(e.target);\n      if (id) goToGradebook(id);\n    });\n    gradesBody.addEventListener('keydown', e => {\n      if (e.key !== 'Enter' && e.key !== ' ') return;\n      const id = gradesRowNavTarget(e.target);\n      if (!id) return;\n      e.preventDefault();\n      goToGradebook(id);\n    });\n\n    const calcModal = document.getElementById('calcModal');\n    function openModal(overlay) {\n      overlay.classList.add('show');\n      document.addEventListener('keydown', escCloseHandler);\n    }\n    function closeModal(overlay) {\n      overlay.classList.remove('show');\n      document.removeEventListener('keydown', escCloseHandler);\n    }\n    function escCloseHandler(e) {\n      if (e.key === 'Escape' && calcModal.classList.contains('show')) closeModal(calcModal);\n    }\n    calcModal.addEventListener('click', e => { if (e.target === calcModal) closeModal(calcModal); });\n\n    const calcCloseBtn = document.getElementById('calcCloseBtn');\n    const calcCategories = document.getElementById('calcCategories');\n    const calcFinalCurrent = document.getElementById('calcFinalCurrent');\n    const calcFinalWant = document.getElementById('calcFinalWant');\n    const calcFinalWeight = document.getElementById('calcFinalWeight');\n    const calcFinalAnswer = document.getElementById('calcFinalAnswer');\n    const calcResetBtn = document.getElementById('calcResetBtn');\n    const calcHeroLabel = document.getElementById('calcHeroLabel');\n    const calcHeroLetter = document.getElementById('calcHeroLetter');\n    const calcHeroPct = document.getElementById('calcHeroPct');\n\n    let calcCourse = null;\n    let calcEdits = {};\n    // True once the user has typed into \"Current grade\" themselves — until\n    // then it stays synced to the live category-based projected grade\n    // above, same idea as an untouched per-assignment input tracking the\n    // real score.\n    let calcFinalCurrentTouched = false;\n\n    function assignKey(catName, title) { return catName + '::' + title; }\n\n    function calcAssignQualifier(a) {\n      if (!a.graded) return ` <span style=\"color:var(--text-faint); font-weight:600;\">(not yet graded)</span>`;\n      return '';\n    }\n\n    function renderCalcCategories() {\n      const gb = GRADEBOOK[calcCourse.id];\n      if (!gb || !Array.isArray(gb.categories) || !gb.categories.length) { calcCategories.innerHTML = '<p class=\"calc-empty\">Nothing graded in this class yet.</p>'; return; }\n      const weighted = gbWeighted(gb);\n      calcCategories.innerHTML = gb.categories.map(cat => {\n        const rows = cat.assignments.map(a => {\n          const key = assignKey(cat.name, a.title);\n          const defaultVal = a.graded ? a.score : '';\n          const val = calcEdits[key] !== undefined ? calcEdits[key] : defaultVal;\n          return `\n            <div class=\"calc-assign-row\">\n              <span class=\"calc-assign-title\">${escapeHtml(a.title)}${calcAssignQualifier(a)}</span>\n              <span class=\"calc-assign-score\">\n                <input class=\"calc-input hyp\" type=\"number\" min=\"0\" placeholder=\"?\" value=\"${escapeHtml(val)}\" data-key=\"${escapeHtml(key)}\" data-points=\"${escapeHtml(a.points)}\" aria-label=\"Score for ${escapeHtml(a.title)}, out of ${escapeHtml(a.points)}, extra credit above ${escapeHtml(a.points)} allowed\"><span class=\"calc-out-of\">/ ${escapeHtml(a.points)}</span>\n              </span>\n            </div>\n          `;\n        }).join('');\n        return `\n          <div class=\"calc-category\">\n            <div class=\"calc-category-head\">\n              <span class=\"calc-category-name\">${escapeHtml(cat.name)}</span>\n              <span class=\"calc-category-weight\" data-base-weight=\"${escapeHtml(cat.weight)}\">${escapeHtml(gbWeightLabel(cat, weighted))}</span>\n            </div>\n            ${rows}\n          </div>\n        `;\n      }).join('');\n    }\n\n    function recomputeCalc() {\n      const gb = GRADEBOOK[calcCourse.id];\n      const cats = gb && Array.isArray(gb.categories) ? gb.categories : [];\n      const weighted = gbWeighted(gb);\n      let overall = 0, weightUsed = 0, allEarned = 0, allPossible = 0;\n      cats.forEach(cat => {\n        let earned = 0, possible = 0;\n        cat.assignments.forEach(a => {\n          const key = assignKey(cat.name, a.title);\n          const raw = calcEdits[key];\n          let scoreToUse = null;\n          if (raw !== undefined && raw !== '' && !isNaN(Number(raw))) {\n            scoreToUse = Number(raw);\n          } else if (a.graded) {\n            scoreToUse = a.score;\n          }\n          // else: still ungraded and no hypothetical entered — excluded,\n          // same as before (doesn't count as a zero).\n          if (scoreToUse !== null) { earned += scoreToUse; possible += a.points; }\n        });\n        if (possible > 0) {\n          const w = Number(cat.weight) > 0 ? Number(cat.weight) : 0;\n          overall += (earned / possible) * 100 * w; weightUsed += w;\n          allEarned += earned; allPossible += possible;\n        }\n      });\n      const raw = weighted ? (weightUsed > 0 ? overall / weightUsed : null) : (allPossible > 0 ? (allEarned / allPossible) * 100 : null);\n      if (raw === null || !isFinite(raw)) {\n        calcHeroLetter.textContent = '—';\n        calcHeroLetter.style.color = '';\n        calcHeroPct.textContent = '';\n        calcHeroLabel.textContent = Object.keys(calcEdits).length > 0 ? 'Projected grade' : 'Current grade';\n        calcCategories.querySelectorAll('.calc-category').forEach((box, i) => {\n          const cat = cats[i];\n          if (cat) box.querySelector('.calc-category-weight').textContent = gbWeightLabel(cat, weighted);\n        });\n        if (!calcFinalCurrentTouched) calcFinalCurrent.value = '';\n        updateFinalAnswer();\n        return;\n      }\n\n      const pct = Math.max(0, Math.min(100, raw));\n      const letter = letterFromPct(pct);\n      calcHeroLetter.textContent = letter;\n      calcHeroLetter.style.color = GRADE_COLOR[gradeBand(letter)];\n      calcHeroPct.textContent = `${pct.toFixed(1)}%`;\n      calcHeroLabel.textContent = Object.keys(calcEdits).length > 0 ? 'Projected grade' : 'Current grade';\n\n      calcCategories.querySelectorAll('.calc-category').forEach((box, i) => {\n        const cat = cats[i];\n        if (cat) box.querySelector('.calc-category-weight').textContent = gbWeightLabel(cat, weighted);\n      });\n\n      // Keep \"Current grade\" synced to the live projected grade above\n      // unless the user has typed their own number in — same touched-flag\n      // idiom used for the per-assignment inputs.\n      if (!calcFinalCurrentTouched) calcFinalCurrent.value = pct.toFixed(1);\n      updateFinalAnswer();\n    }\n\n    function updateFinalAnswer() {\n      const current = Number(calcFinalCurrent.value);\n      const wantRaw = calcFinalWant.value;\n      const weight = Math.max(1, Math.min(100, Number(calcFinalWeight.value) || 0));\n      if (wantRaw === '' || isNaN(current) || isNaN(weight)) {\n        calcFinalAnswer.textContent = '';\n        return;\n      }\n      const want = Number(wantRaw);\n      if (isNaN(want)) { calcFinalAnswer.textContent = ''; return; }\n      const w = weight / 100;\n      const needed = (want - current * (1 - w)) / w;\n      if (needed > 100) {\n        const bestCase = (current * (1 - w) + 100 * w).toFixed(1);\n        calcFinalAnswer.innerHTML = `Even a perfect <strong>100%</strong> on the final won't get you to <strong>${want}%</strong> — the highest you could reach is <strong>${bestCase}%</strong>.`;\n      } else if (needed <= 0) {\n        calcFinalAnswer.innerHTML = `You're already there — even a <strong>0%</strong> on the final keeps you at or above <strong>${want}%</strong>.`;\n      } else {\n        calcFinalAnswer.innerHTML = `You need <strong>${needed.toFixed(1)}%</strong> on the final exam to get <strong>${want}%</strong> in the class.`;\n      }\n    }\n\n    function openCalcModal(courseId) {\n      const course = findCourse(courseId);\n      if (!course) return;\n      calcCourse = course;\n      calcEdits = {};\n      calcFinalCurrentTouched = false;\n      calcFinalWant.value = '';\n      calcFinalWeight.value = 20;\n      document.getElementById('calcCourseName').textContent = course.name;\n      renderCalcCategories();\n      recomputeCalc();\n      openModal(calcModal);\n    }\n    calcCloseBtn.addEventListener('click', () => closeModal(calcModal));\n\n    calcCategories.addEventListener('input', e => {\n      const input = e.target.closest('.calc-input');\n      if (!input) return;\n      const key = input.dataset.key;\n      let val = input.value;\n      if (val !== '' && Number(val) < 0) { val = '0'; input.value = val; }\n      calcEdits[key] = val;\n      recomputeCalc();\n    });\n\n    calcFinalCurrent.addEventListener('input', () => { calcFinalCurrentTouched = true; updateFinalAnswer(); });\n    calcFinalWant.addEventListener('input', updateFinalAnswer);\n    calcFinalWeight.addEventListener('input', updateFinalAnswer);\n\n    calcResetBtn.addEventListener('click', () => {\n      calcEdits = {};\n      calcFinalCurrentTouched = false;\n      calcFinalWant.value = '';\n      calcFinalWeight.value = 20;\n      renderCalcCategories();\n      recomputeCalc();\n    });\n\n    // Nav — Home/Courses/Assignments are real pages now; Calendar/\n    // Messages/Settings stay visual-only placeholders, same convention\n    // used everywhere else in the app.\n    document.querySelectorAll('.nav-link').forEach(link => {\n      link.addEventListener('click', () => {\n        if (link.dataset.href) { window.location.href = link.dataset.href; return; }\n        document.querySelectorAll('.nav-link').forEach(l => l.classList.remove('active'));\n        link.classList.add('active');\n      });\n    });\n\n    // ------------------------------------------------------------------\n    // Profile menu — same behavior as every other page.\n    // ------------------------------------------------------------------\n    const profileBtn = document.getElementById('profileBtn');\n    (function () {\n      var profile = null;\n      try {\n        var raw = localStorage.getItem('averages_profile');\n        if (raw) profile = JSON.parse(raw);\n      } catch (e) {}\n      if (!profile || !profile.name || !String(profile.name).trim()) profile = Object.assign({}, profile, { name: window.__AVERAGES_NAME__ || '' });\n      if (profile.photo) {\n        profileBtn.style.backgroundImage = 'url(\"' + profile.photo + '\")';\n        profileBtn.style.backgroundSize = 'cover';\n        profileBtn.style.backgroundPosition = 'center';\n        profileBtn.textContent = '';\n        profileBtn.classList.add('has-photo');\n      } else if (profile.name) {\n        if (window.AveragesAvatar) window.AveragesAvatar.paint(profileBtn, profile.name);\n        else profileBtn.textContent = (function (n) { var p = String(n).trim().split(/\\s+/).filter(Boolean); var f = function (w) { return w ? Array.from(w)[0] : ''; }; return (f(p[0]) + (p.length > 1 ? f(p[p.length - 1]) : '')).toUpperCase(); })(profile.name);\n      }\n    })();\n    const profileMenu = document.getElementById('profileMenu');\n    function openProfileMenu() { profileMenu.hidden = false; profileBtn.setAttribute('aria-expanded', 'true'); }\n    function closeProfileMenu() { profileMenu.hidden = true; profileBtn.setAttribute('aria-expanded', 'false'); }\n    profileBtn.addEventListener('click', () => { if (profileMenu.hidden) openProfileMenu(); else closeProfileMenu(); });\n    document.addEventListener('click', e => { if (!profileMenu.hidden && !e.target.closest('.profile-menu-wrap')) closeProfileMenu(); });\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !profileMenu.hidden) { closeProfileMenu(); profileBtn.focus(); } });\n    profileMenu.querySelectorAll('.profile-menu-item').forEach(item => {\n      item.addEventListener('click', () => {\n        if (item.dataset.action === 'settings') { window.location.href = '/settings'; return; }\n        closeProfileMenu();\n      });\n    });\n  \n\n\n    (function () {\n      const SELF = '/grades';\n      const KEY = 'averages_nav_trail';\n      const here = SELF + location.search;\n      const label = (document.title || '').replace(/^Averages\\s*[—-]\\s*/, '') || 'Grades';\n      let trail = [];\n      try { trail = JSON.parse(sessionStorage.getItem(KEY) || '[]'); } catch {}\n      if (!Array.isArray(trail)) trail = [];\n      const last = trail[trail.length - 1];\n      if (last && last.href === here) last.label = label;                 // reload\n      else if (trail.length > 1 && trail[trail.length - 2].href === here) { trail.pop(); trail[trail.length - 1].label = label; } // went back\n      else trail.push({ href: here, label });\n      trail = trail.slice(-20);\n      try { sessionStorage.setItem(KEY, JSON.stringify(trail)); } catch {}\n\n      const btn = document.querySelector('.back-link');\n      const prev = trail[trail.length - 2];\n      if (!btn || !prev) return;\n      const fresh = btn.cloneNode(false);          // same button, minus old click handlers\n      fresh.removeAttribute('onclick');\n      const icon = btn.querySelector('svg');\n      if (icon) fresh.appendChild(icon.cloneNode(true));\n      const text = document.createElement('span');\n      text.textContent = 'Back to ' + prev.label;\n      fresh.appendChild(text);\n      fresh.addEventListener('click', () => { window.location.href = prev.href; });\n      btn.replaceWith(fresh);\n    })();\n  ";

export default function Page() {
  return (
    <LegacyPage
      title={TITLE}
      bodyHtml={BODY_HTML}
      scriptJs={SCRIPT_JS}
      hasUploads={false}
      externalScripts={[]}
      pageId={"grades"}
    />
  );
}
